let currentLanguage = (()=>{try{const saved=localStorage.getItem('rinero-language-choice-v52');if(['en','el','es'].includes(saved))return saved;if(localStorage.getItem('rinero-language')==='el')return 'el';}catch{}const locales=navigator.languages?.length?navigator.languages:[navigator.language||''];const locale=locales.map(value=>String(value).toLowerCase()).find(value=>value.startsWith('es')||value.startsWith('el'));return locale?.startsWith('es')?'es':locale?.startsWith('el')?'el':'en';})();

const countryLocale=language=>language==='es'?'es-CO':language==='el'?'el':'en';
function countryOptions(selected='IE') {
  const locale=countryLocale(currentLanguage);
  let names;
  try { names=new Intl.DisplayNames([locale],{type:'region'}); }
  catch { names=new Intl.DisplayNames(['en'],{type:'region'}); }
  return ISO_COUNTRY_CODES.map(code=>({code,name:names.of(code)||code}))
    .sort((a,b)=>a.name.localeCompare(b.name,locale))
    .map(({code,name})=>`<option value="${code}" ${code===selected?'selected':''}>${esc(name)}</option>`).join('');
}
