  updateRewardMessage();window.customerRewardUpdater=updateRewardMessage;if(window.customerRewardTimer)clearInterval(window.customerRewardTimer);if(rewardReady&&rewardDeadline)window.customerRewardTimer=setInterval(updateRewardMessage,15000);
  $('#cardPrivacyNote').textContent=card.collection_mode==='identified'?'Your contact detail is used only for this loyalty card. No messages are sent. You can delete this card and its contact detail here.':currentLanguage==='el'?'Δεν συλλέγουμε όνομα, τηλέφωνο ή email. Για να διατηρείται η ανώνυμη κάρτα σε αυτή τη συσκευή, αποθηκεύεται ένα τυχαίο ID στο πρόγραμμα περιήγησης μαζί με ένα ασφαλές cookie.':currentLanguage==='es'?'No pedimos nombre, teléfono ni correo. Para conservar esta tarjeta anónima en este dispositivo, se guarda un ID aleatorio en el almacenamiento del navegador junto con una cookie segura.':'No name, phone, or email is collected. To keep this anonymous card available on this device, a random ID is saved in browser storage alongside a secure cookie.';
  $('#addAppleWallet').onclick=async()=>{const button=$('#addAppleWallet');button.disabled=true;try{const result=await api('/api/wallet/apple/handoff',{method:'POST',body:JSON.stringify(token?{token}:{})});if(!result.downloadUrl)throw new Error('The Wallet download could not be prepared.');window.location.assign(result.downloadUrl);}catch(error){toast('Could not open Apple Wallet',error.message);}finally{button.disabled=false;}};
  $('#addGoogleWallet').onclick=async()=>{try{const result=await api('/api/wallet/google');window.location.assign(result.saveUrl);}catch(error){toast('Google Wallet is not ready',error.message);}};
  const userAgent=navigator.userAgent||'';
  const devicePlatform=navigator.userAgentData?.platform||navigator.platform||'';
  const isAppleDevice=/iPhone|iPad|iPod/i.test(userAgent)||(/Mac/i.test(devicePlatform)&&navigator.maxTouchPoints>1);
  const isAndroidDevice=/Android/i.test(userAgent)||/Android/i.test(devicePlatform);
  try{
    const availability=await api('/api/wallet/availability');
    const showApple=Boolean(availability.apple)&&(isAppleDevice||!isAndroidDevice);
    const showGoogle=Boolean(availability.google)&&(isAndroidDevice||!isAppleDevice);
    $('#addAppleWallet').classList.toggle('hidden',!showApple);
    $('#addGoogleWallet').classList.toggle('hidden',!showGoogle);
  }catch{$('#addAppleWallet').classList.add('hidden');$('#addGoogleWallet').classList.add('hidden');}
  $('#deleteCustomerCard').onclick=async()=>{if(!window.confirm('Delete this loyalty card and its associated details and stamp history? This cannot be undone.'))return;try{await api('/api/card',{method:'DELETE',body:'{}'});history.replaceState({},'', '/');$('#customerCard').classList.add('hidden');resetAuth();toast('Card deleted','The card and its stamp history have been removed.');}catch(error){toast('Could not delete card',error.message);}};
