$$('.nav-link[data-section]').forEach(button=>button.onclick=()=>{const staff=button.dataset.section==='staff';$('#dashboardSection').classList.toggle('hidden',staff);$('#staffSection').classList.toggle('hidden',!staff);$('#breadcrumb').textContent=staff?'Add stamps':state.selectedClient?.name||'Agency dashboard';$$('.nav-link[data-section]').forEach(item=>item.classList.toggle('active',item===button));});
let scannedCardUrl='';let cameraScanner=null;
function setScannedCard(url){scannedCardUrl=url;$('#stampButton').disabled=false;$('#redeemButton').disabled=false;$('#scanHelp').textContent='Card scanned. Choose what to do.';$('#staffMessage').className='form-message success-message';$('#staffMessage').textContent='Customer card ready.';}
async function startCardScanner(){if(cameraScanner){try{await cameraScanner.stop();}catch{}cameraScanner.clear();cameraScanner=null;$('#cameraReader').classList.add('hidden');$('#scanCardButton').textContent='Scan customer card';return;}if(typeof Html5Qrcode==='undefined'){toast('Scanner did not load','Use “Camera not working?” to paste the card link.');return;}$('#cameraReader').classList.remove('hidden');$('#scanCardButton').textContent='Stop camera';cameraScanner=new Html5Qrcode('cameraReader');try{await cameraScanner.start({facingMode:'environment'},{fps:10,qrbox:{width:230,height:230}},async text=>{if(!text.startsWith(`${location.origin}/card#`)&&!text.startsWith(`${location.origin}/card/#`)){ $('#scanHelp').textContent='That is the welcome QR. Ask the customer to open their loyalty card and tap “Show cashier my QR”.';return;}scannedCardUrl=text;setScannedCard(text);await cameraScanner.stop();cameraScanner.clear();cameraScanner=null;$('#cameraReader').classList.add('hidden');$('#scanCardButton').textContent='Scan another card';},()=>{});}catch(error){cameraScanner=null;$('#cameraReader').classList.add('hidden');$('#scanCardButton').textContent='Scan customer card';toast('Camera unavailable','Check browser camera permission or enter the card link below.');}}
async function stamp(action){const value=scannedCardUrl||$('#customerToken').value.trim(),match=value.match(/(?:#|\/card\/?#?)([A-Za-z0-9_-]{40,50})\/?$/);if(!value||!match){$('#staffMessage').className='form-message form-error';$('#staffMessage').textContent='Scan the customer QR or enter their private card link.';return;}try{await api('/api/staff/cards',{method:'POST',body:JSON.stringify({cardUrl:`${location.origin}/card/#${match[1]}`,action})});$('#staffMessage').className='form-message success-message';$('#staffMessage').textContent=action==='stamp'?'Stamp added to the customer card.':'Reward redemption recorded.';toast('Done','The customer card has been updated.');scannedCardUrl='';$('#stampButton').disabled=true;$('#redeemButton').disabled=true;$('#customerToken').value='';await loadWorkspace();}catch(error){$('#staffMessage').className='form-message form-error';$('#staffMessage').textContent=error.message;}}
$('#scanCardButton').onclick=startCardScanner;
$('#customerToken').addEventListener('input',()=>{const value=$('#customerToken').value.trim();if(value.match(/(?:#|\/card\/?#?)([A-Za-z0-9_-]{40,50})\/?$/))setScannedCard(value);else{scannedCardUrl='';$('#stampButton').disabled=true;$('#redeemButton').disabled=true;}});
$('#stampButton').onclick=()=>stamp('stamp');$('#redeemButton').onclick=()=>stamp('redeem');

