const languageObserver=new MutationObserver(records=>{for(const record of records){if(record.type==='characterData')translateTextNode(record.target);for(const node of record.addedNodes||[])translateSubtree(node);}});
languageObserver.observe(document.body,{subtree:true,childList:true,characterData:true});
setLanguage(currentLanguage,false);

async function start(){const path=location.pathname;const token=location.hash.slice(1);const invite=/^\/invite\/?$/.test(path)&&/^[A-Za-z0-9_-]{40,50}$/.test(token),reset=/^\/reset-password\/?$/.test(path)&&/^[A-Za-z0-9_-]{40,50}$/.test(token),join=path.match(/^\/join\/([0-9a-f-]{36})$/i),card=/^\/card\/?$/.test(path);try{if(invite){const result=await api('/api/invites/lookup',{method:'POST',body:JSON.stringify({token})});return showInvite(token,result.invite);}if(reset)return showReset(token);if(join)return await customerJoin(join[1]);if(card)return await showCustomerCard(/^[A-Za-z0-9_-]{40,50}$/.test(token)?token:'');await loadWorkspace();}catch(error){if(card){history.replaceState({},'', '/card/');$('#authGate').classList.add('hidden');$('#customerCard').classList.remove('hidden');errorAt($('#customerCardError'),'This card could not be opened here. Reopen it from Apple Wallet or scan its card QR again.');return;}resetAuth();errorAt($('#authError'),error.message.includes('fetch')?'The platform database is not connected. Please contact the Rinero administrator.':error.message);}}
start();
